module LiegesOfLegendre(\n    input [7:0] arr_0,\n    input [7:0] arr_1,\n    input [7:0] arr_2,\n    input [7:0] arr_3,\n    input [7:0] arr_4,\n    input [7:0] arr_5,\n    input [7:0] arr_6,\n    input [7:0] arr_7,\n    input [7:0] k,\n    output winner\n);\n    \n    wire [1:0] g0, g1, g2, g3, g4, g5, g6, g7;\n    wire [1:0] xor_result = g0 ^ g1 ^ g2 ^ g3 ^ g4 ^ g5 ^ g6 ^ g7;\n    assign winner = (xor_result != 2'd0);\n    \n    grundy_unit gu0(.pile(arr_0), .k(k), .grundy(g0));\n    grundy_unit gu1(.pile(arr_1), .k(k), .grundy(g1));\n    grundy_unit gu2(.pile(arr_2), .k(k), .grundy(g2));\n    grundy_unit gu3(.pile(arr_3), .k(k), .grundy(g3));\n    grundy_unit gu4(.pile(arr_4), .k(k), .grundy(g4));\n    grundy_unit gu5(.pile(arr_5), .k(k), .grundy(g5));\n    grundy_unit gu6(.pile(arr_6), .k(k), .grundy(g6));\n    grundy_unit gu7(.pile(arr_7), .k(k), .grundy(g7));\nendmodule\n\nmodule grundy_unit(\n    input [7:0] pile,\n    input [7:0] k,\n    output [1:0] grundy\n);\n    \n    wire k_odd = k[0];\n    \n    // Trailing zero count (d)\n    wire [2:0] d;\n    assign d = (pile[0] == 1'b1) ? 3'd0 :\n              (pile[1] == 1'b1) ? 3'd1 :\n              (pile[2] == 1'b1) ? 3'd2 :\n              (pile[3] == 1'b1) ? 3'd3 :\n              (pile[4] == 1'b1) ? 3'd4 :\n              (pile[5] == 1'b1) ? 3'd5 :\n              (pile[6] == 1'b1) ? 3'd6 : 3'd7;\n    \n    wire [8:0] three_shl_d = 9'd3 << d;\n    wire is_3times_pow2 = (three_shl_d[8] == 1'b0) && (pile == three_shl_d[7:0]);\n    wire cond = is_3times_pow2 ^ d[0];\n    \n    // k even form\n    wire [1:0] g_even = (pile < 8'd3) ? pile[1:0] : {1'b0, ~pile[0]} + 2'd0;\n    \n    // k odd form\n    wire [1:0] g_odd;\n    assign g_odd = (pile < 8'd4) ? pile[1:0] :\n                   (pile[0] == 1'b1) ? 2'd0 :\n                   (cond) ? 2'd1 : 2'd2;\n    \n    assign grundy = k_odd ? g_odd : g_even;\nendmodule